// Build the client-side search index for the ⌘K command palette.
//   node scripts/gen-search-index.mjs
// Produces:
//   public/search-index.json   { athletes: [...], meets: [...], posts: [...] }
//
// Kept out of the JS bundle on purpose — the palette fetches this file on first
// open and the service worker caches it. Regenerated by `npm run data` and as a
// `prebuild` step so it never drifts from data/.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (p) => JSON.parse(readFileSync(join(root, p), "utf8"));

const athletes = read("data/athletes.json");
const performances = read("data/performances.json");
const events = read("data/events.json");
const posts = read("data/blog_posts.json");

const eventName = new Map(events.map((e) => [e.event_id, e.event_name]));

// Top event per athlete — most performances, ties broken by lower event_id, the
// same rule lib/data.ts rosterEntries() uses for roster-card specialties.
const counts = new Map(); // athlete_id -> Map<event_id, n>
for (const p of performances) {
  let m = counts.get(p.athlete_id);
  if (!m) counts.set(p.athlete_id, (m = new Map()));
  m.set(p.event_id, (m.get(p.event_id) ?? 0) + 1);
}
const topEvent = (id) => {
  const m = counts.get(id);
  if (!m) return null;
  let best = null;
  for (const [ev, n] of m) {
    if (!best || n > best.n || (n === best.n && ev < best.ev)) best = { ev, n };
  }
  return best ? eventName.get(best.ev) ?? null : null;
};

// Mirrors lib/athlete.ts.
const isFormer = (a) => !a.active || a.status != null;
const alumniLabel = (a) => {
  if (a.status === "transferred") return "Transferred";
  if (a.graduation_year) return `Class of '${String(a.graduation_year).slice(-2)}`;
  return "Alum";
};

const byName = (a, b) =>
  a.last_name.localeCompare(b.last_name) || a.first_name.localeCompare(b.first_name);

const athleteRows = [...athletes]
  .sort((a, b) => Number(isFormer(a)) - Number(isFormer(b)) || byName(a, b))
  .map((a) => {
    const display = `${a.nickname || a.first_name} ${a.last_name}`;
    const former = isFormer(a);
    const ev = topEvent(a.athlete_id);
    // Prefer the athlete's main event; alumni also get their class year. Fall
    // back to a plain status word for the handful with no scraped marks.
    let sub;
    if (ev) {
      sub =
        former && a.graduation_year
          ? `${ev} · Class of '${String(a.graduation_year).slice(-2)}`
          : ev;
    } else {
      sub = former ? alumniLabel(a) : "Current athlete";
    }
    const row = { id: a.athlete_id, name: display, sub };
    // let "Kristopher" find someone shown as "Kris"
    if (a.nickname && a.nickname.toLowerCase() !== a.first_name.toLowerCase()) {
      row.alt = `${a.first_name} ${a.last_name}`;
    }
    if (former) row.alum = 1;
    return row;
  });

// ---- meets (mirrors lib/data.ts allMeets(): identity from the TFRRS link) ----
const MEET_LINK_RE = /tfrrs\.org\/results\/(\d+)\/\d+\/([^/]+)\//;
const cleanMeetName = (rawSlug) =>
  decodeURIComponent(rawSlug)
    .replace(/_/g, " ")
    .replace(/\s+/g, " ")
    .replace(/\bTF\b/g, "Track & Field")
    .replace(/\bTrack Field\b/g, "Track & Field")
    .trim();
const meetSlug = (meetId, name) =>
  `${meetId}-${name
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")}`;

const meetGroups = new Map(); // meetId -> { rawSlug, date, athletes:Set }
for (const p of performances) {
  const m = p.result_link && p.result_link.match(MEET_LINK_RE);
  if (!m) continue;
  const [, meetId, rawSlug] = m;
  let g = meetGroups.get(meetId);
  if (!g) g = meetGroups.set(meetId, { rawSlug, date: p.date, athletes: new Set() }).get(meetId);
  if (p.date < g.date) g.date = p.date;
  g.athletes.add(p.athlete_id);
}

const fmtDate = (iso) =>
  new Date(iso + "T00:00:00").toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });

const meetRows = [...meetGroups.entries()]
  .map(([meetId, g]) => {
    const name = cleanMeetName(g.rawSlug);
    const n = g.athletes.size;
    return {
      slug: meetSlug(meetId, name),
      name,
      date: g.date,
      sub: `${fmtDate(g.date)} · ${n} ${n === 1 ? "athlete" : "athletes"}`,
    };
  })
  .sort((a, b) => b.date.localeCompare(a.date) || a.name.localeCompare(b.name))
  .map(({ slug, name, sub }) => ({ slug, name, sub }));

// ---- news posts ----
const postRows = [...posts]
  .sort((a, b) => String(b.created_on).localeCompare(String(a.created_on)))
  .map((p) => ({
    id: p.post_id,
    name: p.title,
    sub: p.subheading || (p.created_on ? fmtDate(String(p.created_on).slice(0, 10)) : "News"),
  }));

writeFileSync(
  join(root, "public", "search-index.json"),
  JSON.stringify({ athletes: athleteRows, meets: meetRows, posts: postRows }) + "\n"
);

console.log(
  `wrote public/search-index.json (${athleteRows.length} athletes, ` +
    `${meetRows.length} meets, ${postRows.length} posts)`
);
